/**
 * AIG Real3D V93 | four-species SOURCE-authored dynamic surface attachments.
 *
 * Species share ONE solver; ORIGINAL source meshes and triangles are immutable.
 * A real 3D joint transform carries skin/garment/fur/feather/fin geometry;
 * authored root vertices remain pinned. Source-defined flexible tip vertices
 * respond to damped angular spring + joint acceleration + measured flow data.
 *
 * No sprites, fake hair cards generated by this engine, procedural anatomy,
 * auto-rigging, muscle FEM, collision-certified cloth or fluid simulation.
 */
import {AIG_REAL3D_V92_RIG_SCHEMA} from './aig-real3d-rig-wrap-contact.mjs';
import {createAIG3DMesh,makeAIG3DMaterial} from './aig-real3d-core.mjs';
export const AIG_REAL3D_V93_SCHEMA='AIG_REAL3D_V93_SOURCE_FOUR_SPECIES_SECONDARY_SURFACE_V1';
export const AIG_REAL3D_V93_SPECIES=Object.freeze(['HUMAN','QUADRUPED','BIRD','FISH']);
export const AIG_REAL3D_V93_KINDS=Object.freeze(['SKIN_PATCH','GARMENT','FUR','FEATHER','FIN']);
const fail=x=>{throw Error('REAL3D_V93_'+x);};
const finite=Number.isFinite;
const vec=x=>Array.isArray(x)&&x.length===3&&x.every(finite);
const validId=x=>typeof x==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,47}$/.test(x);
const sha=x=>typeof x==='string'&&/^[0-9a-f]{64}$/i.test(x);
const sum=(a,b)=>a.map((v,i)=>v+b[i]);
const sub=(a,b)=>a.map((v,i)=>v-b[i]);
const mul=(a,t)=>a.map(v=>v*t);
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const length=a=>Math.hypot(...a);
const normalize=a=>{const m=length(a);if(m<1e-9)fail('ZERO_DIRECTION');return mul(a,1/m);};
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
const direction=(transform,p)=>transform.basis.map(row=>dot(row,p));
const point=(transform,p)=>sum(direction(transform,p),transform.shift);
const rotation=(p,pivot,axis,deg)=>{
 const [x,y,z]=axis,t=deg*Math.PI/180,c=Math.cos(t),s=Math.sin(t),k=1-c,
  matrix=[[k*x*x+c,k*x*y-s*z,k*x*z+s*y],
   [k*x*y+s*z,k*y*y+c,k*y*z-s*x],
   [k*x*z-s*y,k*y*z+s*x,k*z*z+c]];
 return sum(pivot,matrix.map(row=>dot(row,sub(p,pivot))));
};
function validateAttachments(rig,manifest){
 if(rig?.schema!==AIG_REAL3D_V92_RIG_SCHEMA||
  manifest?.schema!==AIG_REAL3D_V93_SCHEMA||
  !sha(manifest.sourceSha256)||
  manifest.sourceSha256!==rig.sourceSha256||
  !AIG_REAL3D_V93_SPECIES.includes(manifest.species)||
  !Array.isArray(manifest.items)||manifest.items.length<1||manifest.items.length>32)
  fail('SOURCE_SPECIES_OR_MANIFEST_MISMATCH');
 const jointIDs=new Set(rig.sample(0).worlds.keys()),used=new Set();
 return manifest.items.map((a,index)=>{
  if(!validId(a?.id)||used.has(a.id)||!AIG_REAL3D_V93_KINDS.includes(a.kind)||
   !jointIDs.has(a.jointId)||!a.mesh?.actualXYZTriangles||
   !Array.isArray(a.mesh.positions)||!Array.isArray(a.mesh.normals)||
   !Array.isArray(a.mesh.indices)||a.mesh.positions.length!==a.mesh.normals.length||
   a.mesh.positions.length!==a.mesh.vertexCount*3||
   a.mesh.indices.length!==a.mesh.triangleCount*3||
   !Array.isArray(a.flexWeights)||a.flexWeights.length!==a.mesh.vertexCount||
   !a.flexWeights.every(w=>finite(w)&&w>=0&&w<=1)||
   !Array.isArray(a.pinnedVertices)||!a.pinnedVertices.length||
   a.pinnedVertices.length>=a.mesh.vertexCount||
   !a.pinnedVertices.every(i=>Number.isInteger(i)&&i>=0&&i<a.mesh.vertexCount)||
   !vec(a.bindPivot)||!vec(a.hingeAxis)||!vec(a.flexDirection)||
   Math.abs(length(a.hingeAxis)-1)>.001||
   Math.abs(length(a.flexDirection)-1)>.001||
   Math.abs(dot(a.hingeAxis,a.flexDirection))>.95||
   !finite(a.stiffness)||a.stiffness<=0||a.stiffness>800||
   !finite(a.damping)||a.damping<0||a.damping>80||
   !finite(a.inertia)||a.inertia<=0||a.inertia>50||
   !finite(a.flowCoupling)||Math.abs(a.flowCoupling)>100||
   !finite(a.accelerationCoupling)||Math.abs(a.accelerationCoupling)>100||
   !finite(a.maxDeflectionDeg)||a.maxDeflectionDeg<1||a.maxDeflectionDeg>75)
   fail('ATTACHMENT_SOURCE_WEIGHTS_OR_HINGE_INVALID_'+index);
  used.add(a.id);
  const pinned=new Set(a.pinnedVertices);
  if(pinned.size!==a.pinnedVertices.length||
   a.pinnedVertices.some(i=>a.flexWeights[i]!==0)||
   !a.flexWeights.some(w=>w>0))
   fail('ATTACHMENT_PINNED_ROOT_OR_FLEX_INVALID');
  // Hinge pivot must be explicitly supported by a non-flexing source vertex,
  // not an invented position chosen outside the actual source surface.
  const closest=Math.min(...a.pinnedVertices.map(i=>
   length(sub(a.mesh.positions.slice(i*3,i*3+3),a.bindPivot))));
  if(closest>.02)fail('ATTACHMENT_HINGE_NOT_ON_SOURCE');
  return {...a,axis:normalize(a.hingeAxis),flex:normalize(a.flexDirection)};
 });
}
function validateFlow(flow,lastTime){
 if(!Array.isArray(flow)||!flow.length||flow.length>180||
  flow[0]?.timeSec!==0||
  flow.at(-1)?.timeSec<lastTime||
  flow.some((f,i)=>!finite(f.timeSec)||f.timeSec<0||
   !vec(f.velocityMps)||length(f.velocityMps)>130||
   (i>0&&f.timeSec<=flow[i-1].timeSec)))
  fail('MEASURED_FLOW_SAMPLES_INVALID');
}
function flowAt(flow,t){
 let k=1;while(k<flow.length-1&&flow[k].timeSec<t)k++;
 const a=flow[k-1],b=flow[k],f=clamp((t-a.timeSec)/(b.timeSec-a.timeSec),0,1);
 return sum(mul(a.velocityMps,1-f),mul(b.velocityMps,f));
}
export function createAIGReal3DBiomechanicalAttachments({
 rig,manifest,flowSamples=null,stepSec=1/120
}={}){
 const specs=validateAttachments(rig,manifest);
 if(!finite(stepSec)||stepSec<1/300||stepSec>1/60)
  fail('PHYSICS_INTEGRATION_STEP_INVALID');
 const flow=flowSamples??[{timeSec:0,velocityMps:[0,0,0]},
  {timeSec:rig.lastTimeSec,velocityMps:[0,0,0]}];
 validateFlow(flow,rig.lastTimeSec);
 const sourceMeshes=new Map(specs.map(a=>[a.id,a.mesh]));
 const workingMeshes=new Map(specs.map(a=>[a.id,createAIG3DMesh({
  positions:a.mesh.positions,normals:a.mesh.normals,indices:a.mesh.indices,
  provenance:'V93_SOURCE_AUTHORED_ATTACHMENT_'+a.id
 })]));
 const jointWorld=t=>rig.sample(clamp(t,0,rig.lastTimeSec)).worlds;
 const series=new Map(),last=rig.lastTimeSec;
 const steps=Math.ceil(last/stepSec);
 if(steps>7000)fail('PHYSICS_FRAME_BUDGET_EXCEEDED');
 for(const a of specs){
  const trace=[{timeSec:0,angleRad:0,angularSpeedRadps:0}];
  let angle=0,omega=0;
  for(let i=1;i<=steps;i++){
   const t=Math.min(last,i*stepSec),prior=Math.min(last,(i-1)*stepSec),
    dt=t-prior;
   if(dt<=1e-10)continue;
   const bone=jointWorld(t).get(a.jointId),
    hingeAxisWorld=normalize(direction(bone,a.axis)),
    flexDirWorld=normalize(direction(bone,a.flex)),
    torqueDir=normalize(cross(hingeAxisWorld,flexDirWorld));
   const h=Math.min(.012,last/1000),p0=point(jointWorld(Math.max(0,t-h)).get(a.jointId),a.bindPivot),
    p1=point(bone,a.bindPivot),
    p2=point(jointWorld(Math.min(last,t+h)).get(a.jointId),a.bindPivot),
    acc=mul(sum(sub(p2,p1),sub(p0,p1)),1/(h*h));
   const flowWorld=flowAt(flow,t);
   const torque=a.flowCoupling*dot(flowWorld,torqueDir)-
    a.accelerationCoupling*dot(acc,torqueDir)-
    a.stiffness*angle-a.damping*omega;
   // Symplectic Euler with author-supplied elastic hinge coefficients.
   omega+=dt*torque/a.inertia;
   angle+=dt*omega;
   const bound=a.maxDeflectionDeg*Math.PI/180;
   if(Math.abs(angle)>bound){angle=clamp(angle,-bound,bound);omega=0;}
   if(!finite(angle)||!finite(omega)||Math.abs(omega)>1e5)
    fail('SECONDARY_MOTION_NUMERICAL_DIVERGENCE');
   trace.push({timeSec:t,angleRad:angle,angularSpeedRadps:omega});
  }
  series.set(a.id,trace);
 }
 function secondaryAt(itemId,timeSec){
  const a=series.get(itemId);
  if(!a||!finite(timeSec)||timeSec<0||timeSec>last)
   fail('SECONDARY_TIME_OR_ID_INVALID');
  const idx=Math.min(a.length-1,Math.max(0,Math.ceil(timeSec/stepSec)));
  if(!idx)return a[0].angleRad;
  const before=a[idx-1],after=a[idx],
   ratio=clamp((timeSec-before.timeSec)/(after.timeSec-before.timeSec),0,1);
  return before.angleRad*(1-ratio)+after.angleRad*ratio;
 }
 function pose(timeSec){
  if(!finite(timeSec)||timeSec<0||timeSec>last)
   fail('POSE_OUTSIDE_VERIFIED_SOURCE_TIMELINE');
  const world=rig.sample(timeSec).worlds,result={};
  for(const a of specs){
   const source=sourceMeshes.get(a.id),t=world.get(a.jointId),
    swing=secondaryAt(a.id,timeSec)*180/Math.PI,positions=[],normals=[];
   for(let i=0;i<source.vertexCount;i++){
    const sourceP=source.positions.slice(i*3,i*3+3),
     sourceN=source.normals.slice(i*3,i*3+3),blend=a.flexWeights[i],
     motion=rotation(sourceP,a.bindPivot,a.axis,swing*blend),
     q=point(t,motion);
    const rotatedNormal=rotation(sourceN,[0,0,0],a.axis,swing*blend);
    const n=direction(t,rotatedNormal);
    positions.push(...q);normals.push(...normalize(n));
   }
   result[a.id]={positions,normals,indices:source.indices,
    real3DSourceFaces:source.triangleCount,
    hingeAngleDeg:swing,originalSurfaceNotModified:true};
  }
  return {timeSec,attachments:result,allJointsEvaluated:true,
   originalSourceUnaffected:true};
 }
 const workScene={...rig.workingScene,source:
  'V93_RIG_AND_SOURCE_AUTHORED_BIOMECHANICAL_SURFACES',
  nodes:[...rig.workingScene.nodes,...specs.map(a=>({
   id:'V93'+a.id,parentId:null,mesh:workingMeshes.get(a.id),
   transform:{position:[0,0,0],rotationDeg:[0,0,0],scale:[1,1,1]},
   material:makeAIG3DMaterial(a.material??{}),
   visible:true,kind:'object',
   source:'V93_EXPLICIT_SOURCE_ATTACHMENT_'+a.kind,
   geometryVerifiedAgainstSource:false
  }))],revision:rig.workingScene.revision+1};
 let initialized=false,draws=0,subUploads=0;
 function renderFrame(renderer,timeSec,{
  visibleAttachmentIds=null,visibleRigNodeIds=null,deferDraw=false
 }={}){
  if(typeof renderer?.render!=='function'||
   typeof renderer?.updateMeshVertices!=='function')
   fail('REAL_SOURCE_GPU_RENDERER_REQUIRED');
  if(visibleAttachmentIds!==null&&(
   rig.wrapMode!=='HALF_WRAP'||!Array.isArray(visibleAttachmentIds)||
   visibleAttachmentIds.some(x=>!sourceMeshes.has(x))))
   fail('HALF_WRAP_VISIBILITY_SOURCE_IDS_INVALID');
  if(!initialized){
   const init=renderer.render(workScene);
   if(init?.status!=='WEBGL_XYZ_TRIANGLES_RENDERED')
    fail('INITIAL_GPU_SCENE_NOT_REAL');
   initialized=true;
  }
  rig.updateGPU(renderer,timeSec,{
   showNodes:visibleRigNodeIds,deferCompositeRender:true});
  const frame=pose(timeSec),show=visibleAttachmentIds===null?null:
   new Set(visibleAttachmentIds);
  for(const a of specs){
   const w=workingMeshes.get(a.id),p=frame.attachments[a.id],
    changed=[];
   for(let i=0;i<w.vertexCount;i++){
    const j=i*3;
    if(w.positions[j]!==p.positions[j]||
     w.positions[j+1]!==p.positions[j+1]||
     w.positions[j+2]!==p.positions[j+2]||
     w.normals[j]!==p.normals[j]||
     w.normals[j+1]!==p.normals[j+1]||
     w.normals[j+2]!==p.normals[j+2])changed.push(i);
   }
   if(changed.length){
    const gpu=renderer.updateMeshVertices(w,{
     positions:p.positions,normals:p.normals,changedVertexIndices:changed});
    if(!gpu.originalIndexBufferReused||gpu.fullGPUBufferReallocation)
     fail('GPU_SOURCE_INDEX_REUPLOAD_NOT_ALLOWED');
    subUploads+=gpu.positionSubDataCalls+gpu.normalSubDataCalls;
   }
   workScene.nodes.find(n=>n.id==='V93'+a.id).visible=
    show===null||show.has(a.id);
  }
  const rendered=deferDraw?null:renderer.render(workScene);
  if(rendered&&rendered.status!=='WEBGL_XYZ_TRIANGLES_RENDERED')
   fail('SOURCE_ATTACHMENTS_GPU_DRAW_BLOCKED');
  draws++;
  return {timeSec,renderedTriangles:rendered?.triangles??null,
   originalAttachedTriangles:[...sourceMeshes.values()].reduce((s,m)=>s+m.triangleCount,0),
   originalSkeletonJointsStillAllAnimated:rig.boneCount,
   trueOriginalXYZMeshRender:true,actualGPUFrames:draws,
   sourceAttachmentSubDataCalls:subUploads,sourceNotModified:true};
 }
 return {schema:AIG_REAL3D_V93_SCHEMA,rig,species:manifest.species,
  kinds:specs.map(a=>a.kind),sourceSha256:rig.sourceSha256,
  sourceMeshes,workingMeshes,scene:workScene,
  secondaryAt,pose,renderFrame,sourceAttachmentCount:specs.length,
  stats:()=>({renderedFrames:draws,
   attachmentGPUBufferSubDataCalls:subUploads,
   originalSourceTopologyImmutable:true,
   allBonesCalculatedInFULLandHALF:true,
   independentAnimalScanVerified:false,
   highFidelityHairFeatherClothFluidVerified:false,
   originalSourceSHAIndependentlyAuthenticated:false,
   measuredCinema1080p60FPS:false,productionPASS:false})};
}
